import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Justice (evidence, not a court)","description":"uuidna's recomputable evidence and integrity layer — how it supports justice honestly by making claims verifiable, keeping the flag on the claim never the person, and leaving the ruling to humans and courts. Not a legal system.","frontmatter":{"title":"Justice (evidence, not a court)","description":"uuidna's recomputable evidence and integrity layer — how it supports justice honestly by making claims verifiable, keeping the flag on the claim never the person, and leaving the ruling to humans and courts. Not a legal system."},"headers":[],"relativePath":"docs/justice.md","filePath":"docs/justice.md"}`),a={name:`docs/justice.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="justice-—-evidence-not-a-court" tabindex="-1">Justice — evidence, not a court <a class="header-anchor" href="#justice-—-evidence-not-a-court" aria-label="Permalink to “Justice — evidence, not a court”">​</a></h1><p>uuidna is <strong>not a legal system</strong>. It does not make law, rule, judge, prosecute, or enforce, and it does not certify that anything is compliant or lawful — those are for legislatures, counsel, and courts. What it <em>is</em> is a <strong>recomputable evidence and integrity layer</strong>: it protects by making claims <strong>verifiable</strong>, so a decision rests on something anyone can recheck rather than on trust or authority.</p><h2 id="how-it-protects-—-by-recomputation-not-by-ruling" tabindex="-1">How it protects — by recomputation, not by ruling <a class="header-anchor" href="#how-it-protects-—-by-recomputation-not-by-ruling" aria-label="Permalink to “How it protects — by recomputation, not by ruling”">​</a></h2><ul><li><strong>Anyone can recheck.</strong> Every verdict, receipt, and fact base is a content-address anyone recomputes from the same source. No one has to <em>believe</em> uuidna; they <em>verify</em> it. That protects against a false claim from any side.</li><li><strong>The flag is on the claim, never the person.</strong> The <a href="/trials">trial</a> adjudicates a <em>statement&#39;s</em> integrity — is it backed, does it recompute — not a person&#39;s guilt. Due process in spirit: no accusation, no dossier.</li><li><strong>Nothing hidden, nothing altered.</strong> Content-addressing is tamper-evident: any change moves the receipt. A record cannot be quietly edited to frame or to exonerate.</li><li><strong>A false trial cannot survive recomputation.</strong> <a href="/mcp">Forensics</a> audits a statement against the receipts — a fabricated citation, a false address, an unbacked legal claim are exposed by rechecking, not by opinion.</li><li><strong>Priority and authorship are provable.</strong> An in-house <a href="/mcp">prior-art record</a> plus an external, signed timestamp anchor (NIST Beacon) establish <em>what</em> was published and <em>when</em>, re-verifiable by anyone.</li></ul><h2 id="the-tools-all-recomputable-all-in-house-except-the-anchors" tabindex="-1">The tools (all recomputable, all in-house except the anchors) <a class="header-anchor" href="#the-tools-all-recomputable-all-in-house-except-the-anchors" aria-label="Permalink to “The tools (all recomputable, all in-house except the anchors)”">​</a></h2><table tabindex="0"><thead><tr><th>tool</th><th>what it delivers</th></tr></thead><tbody><tr><td><code>uuidna_legal_facts</code></td><td>the recomputable legal <strong>fact base</strong> (licence, attribution, ledger receipt, standards cited) — inputs an audit starts from, <strong>not an opinion</strong></td></tr><tr><td><code>uuidna_prior_art</code></td><td>an in-house <strong>defensive-publication</strong> manifest: what/who/integrity/terms, folded to one address</td></tr><tr><td><code>uuidna_anchor</code></td><td>the external <strong>when</strong> — a signed NIST Beacon pulse folded in, a re-verifiable <em>not-before</em> bound</td></tr><tr><td><code>uuidna_forensics</code></td><td>audit an agent <strong>statement against the receipts</strong> — false trials exposed</td></tr><tr><td><code>uuidna_evidence</code></td><td>a recomputable <strong>evidence bundle</strong> a court recomputes rather than trusts</td></tr></tbody></table><h2 id="what-it-does-not-do" tabindex="-1">What it does <strong>not</strong> do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to “What it does not do”">​</a></h2><ul><li>It does <strong>not</strong> rule, sentence, prosecute, or accuse a person. It hands humans recheckable facts; <strong>the ruling is a human&#39;s and a court&#39;s.</strong></li><li>It does <strong>not</strong> certify legal compliance — its own gate refuses &quot;all laws met&quot; as unbacked.</li><li>It does <strong>not</strong> claim to protect everyone from everything. It protects the one thing a fold can: it makes the <em>record</em> honest — verifiable, attributed, tamper-evident — so the people entitled to judge do so on the merits.</li></ul><p>Justice needs evidence that recomputes and a human to weigh it. uuidna delivers the first and defers the second, by design. <a href="/trials">The trial charter</a> · <a href="/license">The licence</a> · <a href="/privacy">Privacy by design</a>. Integrity, not truth.</p>`,9)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};